#include <iostream>
#include <string>
#include <algorithm>

// Chuyen doi so thap phan sang chuoi nhi phan (thuat toan chia lien tiep)
std::string decimalToBinary(unsigned int n) {
    if (n == 0) return "0";
    std::string bin;
    while (n > 0) {
        bin.push_back((n % 2 == 0) ? '0' : '1');
        n /= 2;
    }
    std::reverse(bin.begin(), bin.end());
    return bin;
}

// Chuyen doi chuoi nhi phan sang so thap phan (khai trien luy thua co so 2)
unsigned int binaryToDecimal(const std::string& bin) {
    unsigned int val = 0;
    for (char c : bin) {
        val = val * 2 + (c - '0');
    }
    return val;
}

int main() {
    // Kiem tra thuat toan voi vi du sach giao khoa: 123 -> 1111011
    unsigned int num = 123;
    std::string binStr = decimalToBinary(num);
    std::cout << "Decimal " << num << " in binary: " << binStr << "\n";

    // Kiem tra nguoc lai voi 10101011 -> 171
    std::string sampleBin = "10101011";
    unsigned int decVal = binaryToDecimal(sampleBin);
    std::cout << "Binary " << sampleBin << " in decimal: " << decVal << "\n";

    // Tinh nang C++17: Binary literal 0b
    int cxx17_lit = 0b1111011;
    std::cout << "C++17 binary literal 0b1111011 evaluated as: " << cxx17_lit << "\n";
    return 0;
}

#include <iostream>
#include <string>

// Chuyen mot ky tu hex sang chuoi 4-bit
std::string hexCharToNibble(char h) {
    int val = 0;
    if (h >= '0' && h <= '9') val = h - '0';
    else if (h >= 'A' && h <= 'F') val = h - 'A' + 10;
    else if (h >= 'a' && h <= 'f') val = h - 'a' + 10;

    std::string nibble;
    for (int i = 3; i >= 0; --i) {
        nibble.push_back(((val >> i) & 1) ? '1' : '0');
    }
    return nibble;
}

// Chuyen doi chuoi hex sang chuoi nhi phan truc tiep
std::string hexToBinary(const std::string& hex) {
    std::string result;
    for (char c : hex) {
        result += hexCharToNibble(c);
    }
    size_t first1 = result.find_first_not_of('0');
    return (first1 == std::string::npos) ? "0" : result.substr(first1);
}

int main() {
    std::string hexVal = "7B";
    std::cout << "Hex 0x" << hexVal << " to Binary: " << hexToBinary(hexVal) << "\n";

    // In cung mot gia tri so nguyen o cac he dem qua stream manipulators
    unsigned int num = 123;
    std::cout << "Decimal: " << std::dec << num << "\n";
    std::cout << "Hexadecimal: 0x" << std::hex << std::uppercase << num << "\n";
    std::cout << "Octal: 0" << std::oct << num << "\n";
    return 0;
}
